/* Generated by scripts/build-fallback.php — edit resources/js/check-out.js instead. */
/*
|------------------------------------------------------------------------------
| Check Out Guest
|------------------------------------------------------------------------------
| Opens the four side modals, hides card fields unless a card is being used,
| expands a department's lines, and re-reads the page with a discount applied.
|
| Every form inside the modals is a plain POST, so the screen still works if
| this file never loads — the modals would simply all be visible.
*/

(function () {
    'use strict';

    const $ = (sel, root) => (root || document).querySelector(sel);
    const $$ = (sel, root) => Array.prototype.slice.call((root || document).querySelectorAll(sel));

    /* ── Modals ─────────────────────────────────────────────────────────── */

    function close(modal) {
        modal.classList.remove('is-open');
        document.body.style.overflow = '';
    }

    $$('[data-open]').forEach(function (button) {
        button.addEventListener('click', function () {
            const modal = $('[data-modal="' + button.getAttribute('data-open') + '"]');
            if (!modal) return;

            modal.classList.add('is-open');
            document.body.style.overflow = 'hidden';

            const first = $('input:not([type=hidden]), select', modal);
            if (first) first.focus();
        });
    });

    $$('[data-modal]').forEach(function (modal) {
        $$('[data-modal-close]', modal).forEach((b) => b.addEventListener('click', () => close(modal)));

        modal.addEventListener('click', function (event) {
            if (event.target === modal) close(modal);
        });
    });

    document.addEventListener('keydown', function (event) {
        if (event.key !== 'Escape') return;

        $$('[data-modal].is-open').forEach(close);
    });

    /* ── Card fields, in every form that has them ───────────────────────── */

    $$('[data-pay-type]').forEach(function (select) {
        // The card block belongs to the same form as the pay type that drives
        // it — a page with two payment forms must not cross the wires.
        const form = select.closest('form') || document;
        const fields = $$('[data-card-field]', form);
        const needsCard = ['credit_card', 'debit_card'];

        function sync() {
            const isCard = needsCard.indexOf(select.value) !== -1;

            fields.forEach(function (field) {
                field.hidden = !isCard;

                if (!isCard) {
                    $$('input, select', field).forEach((el) => { el.value = ''; });
                }
            });
        }

        select.addEventListener('change', sync);
        sync();
    });

    /* ── Folio lines ────────────────────────────────────────────────────── */

    $$('[data-toggle-lines]').forEach(function (button) {
        button.addEventListener('click', function () {
            const row = $('[data-lines="' + button.getAttribute('data-toggle-lines') + '"]');
            if (!row) return;

            row.hidden = !row.hidden;
            button.textContent = row.hidden ? 'View' : 'Hide';
        });
    });

    /* ── Add Folio: picking a service fills the line in ─────────────────── */

    const servicePick = $('[data-service-pick]');

    if (servicePick) {
        servicePick.addEventListener('change', function () {
            const option = servicePick.selectedOptions[0];
            if (!option || !option.value) return;

            const form = servicePick.closest('form');
            const name = $('[data-charge-name]', form);
            const price = $('[data-charge-price]', form);
            const tax = $('[data-charge-tax-choice]', form);

            if (name && !name.value) name.value = option.dataset.name || '';
            if (price) price.value = option.dataset.price || 0;

            /*
             * The service's own tax, offered rather than imposed: the clerk can
             * put it straight back to No Tax, and a service that names no tax
             * leaves the dropdown exactly where it was.
             */
            if (tax) {
                const wanted = option.dataset.taxChoice || 'none';
                const exists = Array.prototype.some.call(tax.options, function (o) {
                    return o.value === wanted;
                });

                tax.value = exists ? wanted : 'none';
            }
        });
    }

    /* ── Discount preview ───────────────────────────────────────────────── */

    const apply = $('[data-apply-discount]');

    if (apply) {
        apply.addEventListener('click', function () {
            const form = apply.closest('form');
            const mode = $('[data-discount-mode]', form);
            const value = $('[name="discount_value"]', form);

            // Re-read the page with the discount in the query string: the
            // server works the figure out, so the screen and the bill can
            // never disagree about what a discount comes to.
            const url = new URL(window.location.href);

            url.searchParams.set('discount_mode', mode ? mode.value : 'amount');
            url.searchParams.set('discount_value', value ? value.value || '0' : '0');

            window.location.href = url.toString();
        });
    }

    /* ── F10 checks out, the way the old system did ─────────────────────── */

    const checkoutForm = $('#checkout-form');

    if (checkoutForm) {
        document.addEventListener('keydown', function (event) {
            if (event.key !== 'F10') return;
            if ($$('[data-modal].is-open').length) return;

            event.preventDefault();
            checkoutForm.requestSubmit();
        });
    }
})();
